    ARM::Expire::MinimumExpireDays = 1;
    ARM::Expire::MaximumExpireDays = 7;
    ARM::Expire::DeadlineDays = 2982;
    ARM::Funds::BaseAdvance = 46000.0f;
    ARM::Funds::BaseReward = 120000.0f;
    ARM::Funds::BaseFailure = 0.0f;
    ARM::Funds::SolarEjectionMultiplier = 1.25f;
    ARM::Science::BaseReward = 16.0f;
    ARM::Science::SolarEjectionMultiplier = 1.0f;
    ARM::Reputation::BaseReward = 26.0f;
